PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE potions (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  description_raw TEXT,
  rarity TEXT,
  rarity_key TEXT,
  pool TEXT,
  image_url TEXT,
  compendium_order INTEGER
);
CREATE TABLE relics (
    id                  TEXT PRIMARY KEY,
    name                TEXT NOT NULL,
    description         TEXT,
    description_raw     TEXT,
    flavor              TEXT,
    rarity              TEXT,
    rarity_key          TEXT,
    pool                TEXT,
    merchant_price_base INTEGER,
    merchant_price_min  INTEGER,
    merchant_price_max  INTEGER,
    image_url           TEXT,
    image_variants      TEXT,  
    name_variants       TEXT,   
    notes               TEXT,   
    compendium_order    INTEGER
);
